{
	"name": "@icaruk/zai-peak-hours",
	"version": "0.8.0",
	"type": "module",
	"description": "OpenCode plugin to display z.ai peak hours information with automatic timezone detection",
	"main": "dist/index.js",
	"types": "dist/index.d.ts",
	"exports": {
		".": {
			"import": "./dist/index.js",
			"types": "./dist/index.d.ts"
		}
	},
	"scripts": {
		"build": "tsc",
		"dev": "tsc --watch",
		"prepublishOnly": "npm run build"
	},
	"keywords": [
		"opencode",
		"plugin",
		"peak-hours",
		"timezone",
		"cli"
	],
	"author": "Icaruk",
	"license": "MIT",
	"devDependencies": {
		"@types/node": "^20.0.0",
		"typescript": "^5.0.0"
	},
	"files": [
		"dist",
		"README.md",
		"LICENSE"
	],
	"repository": {
		"type": "git",
		"url": "git+https://github.com/Icaruk/zai-peak-hours.git"
	},
	"engines": {
		"node": ">=18.0.0"
	}
}
